import{_ as n,a0 as o,w as r,s as p,ao as u,I as s,x as a,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8","title":"如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0","tag":"201911","desc":""},"relativePath":"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8.md"};function h(c,t,x,g,b,k){const i=o("Link");return r(),p("div",null,[t[15]||(t[15]=u(`<h1 id="如何在-centos-8-rhel-8-上安装-virtualbox-6-0" tabindex="-1">如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安装-virtualbox-6-0" aria-label="Permalink to “如何在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201911/30/095031gbnm59ux0dw979wb.jpg" alt=""></p><p>VirtualBox 是一款自由开源的虚拟化工具，它允许技术人员同时运行多个不同风格的虚拟机（VM）。它通常用于运行桌面（Linux 和 Windows），当人们尝试探索新的 Linux 发行版的功能或希望在 VM 中安装 OpenStack、Ansible 和 Puppet 等软件时，它会非常方便，在这种情况下，我们可以使用 VirtualBox 启动 VM。</p><p>VirtualBox 被分类为 2 类虚拟机管理程序，这意味着它需要一个现有的操作系统，在上面安装 VirtualBox 软件。VirtualBox 提供功能来创建本机网络或 NAT 网络。在本文中，我们将演示如何在 CentOS 8 和 RHEL 8 系统上安装最新版本的 VirtualBox 6.0，并演示如何安装 VirtualBox 扩展。</p><h3 id="在-centos-8-rhel-8-上安装-virtualbox-6-0-的安装步骤" tabindex="-1">在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 的安装步骤 <a class="header-anchor" href="#在-centos-8-rhel-8-上安装-virtualbox-6-0-的安装步骤" aria-label="Permalink to “在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 的安装步骤”">​</a></h3><h4 id="步骤-1-启用-virtualbox-和-epel-仓库" tabindex="-1">步骤 1： 启用 VirtualBox 和 EPEL 仓库 <a class="header-anchor" href="#步骤-1-启用-virtualbox-和-epel-仓库" aria-label="Permalink to “步骤 1： 启用 VirtualBox 和 EPEL 仓库”">​</a></h4><p>登录到你的 CentOS 8 或 RHEL 8 系统并打开终端，执行以下命令并启用 VirtualBox 和 EPEL 包仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf config-manager --add-repo=https://download.virtualbox.org/virtualbox/rpm/el/virtualbox.repo</span></span></code></pre></div><p>使用以下 <code>rpm</code> 命令导入 Oracle VirtualBox 公钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# rpm --import https://www.virtualbox.org/download/oracle_vbox.asc</span></span></code></pre></div><p>使用以下 <code>dnf</code> 命令启用 EPEL 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm -y</span></span></code></pre></div><h4 id="步骤-2-安装-virtualbox-构建工具和依赖项" tabindex="-1">步骤 2： 安装 VirtualBox 构建工具和依赖项 <a class="header-anchor" href="#步骤-2-安装-virtualbox-构建工具和依赖项" aria-label="Permalink to “步骤 2： 安装 VirtualBox 构建工具和依赖项”">​</a></h4><p>运行以下命令来安装所有 VirtualBox 构建工具和依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install binutils kernel-devel kernel-headers libgomp make patch gcc glibc-headers glibc-devel dkms -y</span></span></code></pre></div><p>成功安装上面的依赖项和构建工具后，使用 <code>dnf</code> 命令继续安装 VirtualBox。</p><h4 id="步骤-3-在-centos-8-rhel-8-上安装-virtualbox-6-0" tabindex="-1">步骤 3： 在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0 <a class="header-anchor" href="#步骤-3-在-centos-8-rhel-8-上安装-virtualbox-6-0" aria-label="Permalink to “步骤 3： 在 CentOS 8 / RHEL 8 上安装 VirtualBox 6.0”">​</a></h4><p>如果希望在安装之前列出 VirtualBox 的可用版本，请执行以下 dnf 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf search virtualbox</span></span>
<span class="line"><span>Last metadata expiration check: 0:14:36 ago on Sun 17 Nov 2019 04:13:16 AM GMT.</span></span>
<span class="line"><span>=============== Summary &amp; Name Matched: virtualbox =====================</span></span>
<span class="line"><span>VirtualBox-5.2.x86_64 : Oracle VM VirtualBox</span></span>
<span class="line"><span>VirtualBox-6.0.x86_64 : Oracle VM VirtualBox</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>让我们使用以下 <code>dnf</code> 命令安装最新版本的 VirtualBox 6.0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install VirtualBox-6.0 -y</span></span></code></pre></div><p>如果有本地用户希望将 usb 设备连接到 VirtualBox VM，那么他/她应该是 <code>vboxusers</code> 组的一员，请使用下面的 <code>usermod</code> 命令将本地用户添加到 <code>vboxusers</code> 组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# usermod -aG vboxusers pkumar</span></span></code></pre></div><h4 id="步骤-4-访问-centos-8-rhel-8-上的-virtualbox" tabindex="-1">步骤 4： 访问 CentOS 8 / RHEL 8 上的 VirtualBox <a class="header-anchor" href="#步骤-4-访问-centos-8-rhel-8-上的-virtualbox" aria-label="Permalink to “步骤 4： 访问 CentOS 8 / RHEL 8 上的 VirtualBox”">​</a></h4><p>有两种方法可以访问 VirtualBox，在命令行输入 <code>virtualbox</code> 然后回车：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# virtualbox</span></span></code></pre></div><p>在桌面环境中，在搜索框中搜索 “VirtualBox”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Access-VirtualBox-CentOS8.jpg" alt="Access-VirtualBox-CentOS8"></p><p>单击 VirtualBox 图标：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/VirtualBox-CentOS8.jpg" alt="VirtualBox-CentOS8"></p><p>这确认 VirtualBox 6.0 已成功安装，让我们安装它的扩展包。</p><h4 id="步骤-5-安装-virtualbox-6-0-扩展包" tabindex="-1">步骤 5： 安装 VirtualBox 6.0 扩展包 <a class="header-anchor" href="#步骤-5-安装-virtualbox-6-0-扩展包" aria-label="Permalink to “步骤 5： 安装 VirtualBox 6.0 扩展包”">​</a></h4><p>顾名思义，VirtualBox 扩展包用于扩展 VirtualBox 的功能。它添加了以下功能：</p><ul><li>USB 2.0 和 USB 3.0 支持</li><li>虚拟 RDP（VRDP）</li><li>磁盘镜像加密</li><li>Intel PXE 启动</li><li>主机网络摄像头</li></ul><p>使用下面的 <code>wget</code> 命令下载 Virtualbox 扩展包到下载文件夹中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ cd Downloads/</span></span>
<span class="line"><span>[root@linuxtechi Downloads]$ wget https://download.virtualbox.org/virtualbox/6.0.14/Oracle_VM_VirtualBox_Extension_Pack-6.0.14.vbox-extpack</span></span></code></pre></div><p>下载后，打开 VirtualBox 并依次点击 “File -&gt; Preferences -&gt; Extension”，然后点击 “+” 号图标添加下载的扩展包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-VirtualBox-Extension-Pack-CentOS8.jpg" alt="Install-VirtualBox-Extension-Pack-CentOS8"></p><p>单击 “Install” 开始安装扩展包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Accept-VirtualBox-Extension-Pack-License-CentOS8.jpg" alt="Accept-VirtualBox-Extension-Pack-License-CentOS8"></p><p>单击 “I Agree” 接受 VirtualBox 扩展包许可证。</p><p>成功安装 VirtualBox 扩展包后，我们将看到下面的页面，单击 “OK” 并开始使用 VirtualBox。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/VirtualBox-Extension-Pack-Install-Message-CentOS8.jpg" alt="VirtualBox-Extension-Pack-Install-Message-CentOS8"></p><p>本文就是这些了，我希望这些步骤可以帮助你在 CentOS 8 和 RHEL 8 系统上安装 VirtualBox 6.0。请分享你的宝贵的反馈和意见。</p><hr>`,45)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/install-virtualbox-6-centos-8-rhel-8/"},{default:l(()=>[...t[0]||(t[0]=[a("https://www.linuxtechi.com/install-virtualbox-6-centos-8-rhel-8/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[2]||(t[2]=[a("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:l(()=>[...t[4]||(t[4]=[a("geekpi",-1)])]),_:1}),t[9]||(t[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[a("Linux中国",-1)])]),_:1}),t[14]||(t[14]=a(" 荣誉推出",-1))])])}const B=n(d,[["render",h]]);export{f as __pageData,B as default};
